mapper.select:
SELECT 
FROM ocean_gis.gis_import_export_record r
JOIN ocean_gis.gis_data_set ds ON ds.id = r.data_set_id
WHERE r.deleted = 0
  AND r.operation_type = 'IMPORT'

    AND r.data_set_id = #{dataSetId}


    AND ds.category_id = #{categoryId}


    AND r.record_no LIKE CONCAT('%', #{recordNo}, '%')


    AND r.record_status = #{recordStatus}


    AND r.create_time >= #{createTimeStart}


    AND r.create_time <= #{createTimeEnd}


    AND EXISTS (
        SELECT 1
        FROM ocean_gis.gis_file_opt_record_item item
        LEFT JOIN ocean_gis.gis_file_meta fm ON fm.id = item.file_meta_id
        WHERE item.record_id = r.id
          AND (fm.id IS NULL OR fm.deleted = 0)

            AND COALESCE(item.original_name, fm.original_name)
                LIKE CONCAT('%', #{originalName}, '%')


            AND fm.extension = #{extension}


            AND fm.upload_status = #{uploadStatus}

    )

ORDER BY r.create_time DESC, r.id DESC
